 edges=[];ras=[]
 for i,r0 in enumerate(d['relations'],1):
  r=copy.deepcopy(r0);target=r['target'];assert target in N
  r.update(proposal_id=PRE+pid+'_'+str(i),source=pid,type='critique' if r['relationship_kind']=='critique' else 'connection',directed=r.get('directed',True),classification_basis='editorial_review')
  # Only groups have field rosters. Person-to-person testimony is left as a graph relation.
  if N[target].get('entry_kind')!='person':
   existing=next((row for row in N[target].get('representative_people',[]) if row['person_id']==pid),None)
