 contexts=[dict(node=n['id'],rows=[copy.deepcopy(r) for r in n.get('representative_people',[]) if r['person_id']==pid],strands=[dict(id=s['id'],title=s['title']) for s in n.get('strands',[]) if pid in s.get('person_ids',[])]) for n in G['nodes'] if any(r['person_id']==pid for r in n.get('representative_people',[]))]
 usedold=set(d['old'])|{s for e in edges for s in e['source_ids'] if s in S}
 pn=dict(person_id=pid,label=label,selection=q,identity_scope=identity,existing_coverage=contexts,existing_sources_reused=[copy.deepcopy(S[s]) for s in sorted(usedold)],new_source_scopes=d['sources'],reading_limit=d['scope'],life_status_record=pid+'/life-status.json',events=d['events'],relations=edges)
